    public function __construct(
        public string $name = 'sparkles',
    ) {}

    /**
     * Determine whether the requested icon is a solid brand mark.
     */
    public function isBrand(): bool
    {
        return array_key_exists($this->name, self::BRAND);
    }

    /**
     * The inner markup of the requested icon.
     */
    public function content(): string
    {
        return self::BRAND[$this->name] ?? self::OUTLINE[$this->name] ?? self::OUTLINE['sparkles'];
    }

    public function render(): View|Closure
    {
        return view('components.icon');
    }
